:root {
  --ink: #20343d;
  --paper: #fffdf7;
  --accent: #ff6f91;
}

.passport {
  width: 450px;
  padding: 18px;
  border: 2px solid var(--ink);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.passport-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 14px;
  border-bottom: 2px dashed var(--ink);
}

.scoop {
  font-size: 34px;
}

.identity {
  flex: 1;
}

.identity p {
  margin: 0 0 3px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.4px;
}

.identity h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
}

.stamp {
  padding: 6px 8px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  color: var(--accent);
  font-size: 11px;
  letter-spacing: 0.6px;
}

.note {
  margin: 14px 0 12px;
  font-size: 14px;
  line-height: 1.35;
}

.passport button {
  border: 0;
  border-radius: 8px;
  padding: 9px 13px;
  background: var(--ink);
  color: var(--paper);
  font-size: 13px;
  font-weight: 800;
}
